<style is:inline>
/* Only the newly selected study fields; existing originals/owners stay unchanged. */
.ck-genesis-targum-day { margin: .8rem 0; }
.ck-genesis-targum-day h4 { font-size: 1.08rem; line-height: 1.5; margin: .4rem 0; }
.ck-genesis-targum-day p, .ck-genesis-english-owner .ck-source-qualification p { font-size: 1rem; line-height: 1.65; margin: .5rem 0; }
.ck-genesis-english-owner > .ck-en-line { font-style: normal; }
.ck-genesis-english-owner > .ck-en-line > small { display: block; font-style: normal; font-weight: 600; }
</style>
